import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { packagesDir } from '../util/paths.mjs';
import { byCodeUnit } from '../util/sort.mjs';
import { writeGenerated } from '../util/write.mjs';

const OUT_DIR = join(packagesDir, 'assets', 'src', 'generated', 'icons');

const HEADER =
  '// Generated by @bwp-web/codegen from spec/icons.json. Do not edit.\n';

/**
 * A stable fingerprint of one variant's geometry.
 *
 * The React, SVG and Flutter targets all draw the same `d` strings, and the parity suite has to
 * prove that. Recording the strings themselves in every target's manifest would duplicate the
 * 358 KB of path data once per target, so each manifest records a digest instead: equal digests
 * mean equal geometry, and that is the whole question parity asks. `fillRule` is spelled out
 * rather than left implicit, so a target that drops the attribute is a different digest.
 */
export function geometryDigest(paths) {
  const canonical = JSON.stringify(
    paths.map((p) => ({ d: p.d, fillRule: p.fillRule ?? 'nonzero' })),
  );
  return createHash('sha256').update(canonical).digest('hex');
}

const quote = (text) =>
  `'${text.replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;

const pathLiteral = (path) =>
  path.fillRule === 'evenodd'
    ? `{ d: ${quote(path.d)}, fillRule: 'evenodd' }`
    : `{ d: ${quote(path.d)} }`;

const geometryLiteral = (name, geometry) =>
  `const ${name}: IconGeometry = {\n` +
  `  viewBox: ${quote(geometry.viewBox.join(' '))},\n` +
  `  paths: [${geometry.paths.map(pathLiteral).join(', ')}],\n` +
  `};\n`;

// The catalog description is prose from Figma and can say anything; only a comment terminator
// would break out of the JSDoc.
const jsdoc = (icon) =>
  `/**\n * ${icon.description.replaceAll('*/', '* /')}\n *\n * @category ${icon.category}\n */\n`;

/**
 * Renders every icon module, the barrel and the manifest, as data.
 *
 * Returning strings rather than writing them keeps the test suite off the disk and makes the
 * "no `#111111` anywhere" assertion a property of what this function produces, not of whatever
 * happens to be checked in.
 */
export function renderReactIcons(spec) {
  const stems = Object.keys(spec.icons).sort(byCodeUnit);
  const modules = [];
  const icons = {};

  for (const stem of stems) {
    const icon = spec.icons[stem];
    // One component function per icon rather than a call to a shared factory: a bundler can see
    // that an unimported function is unreachable without following a call, and React DevTools
    // shows the icon's own name.
    const tsx =
      HEADER +
      `import {\n  Icon,\n  type IconGeometry,\n  type IconProps,\n} from '../../icon.js';\n\n` +
      geometryLiteral('outline', icon.variants.outline) +
      '\n' +
      geometryLiteral('solid', icon.variants.solid) +
      '\n' +
      jsdoc(icon) +
      `export function ${icon.component}(props: IconProps) {\n` +
      `  return <Icon {...props} outline={outline} solid={solid} />;\n` +
      `}\n`;
    modules.push({ stem, component: icon.component, file: `${stem}.tsx`, tsx });

    icons[stem] = {
      component: icon.component,
      variants: Object.fromEntries(
        ['outline', 'solid'].map((variant) => {
          const geometry = icon.variants[variant];
          return [
            variant,
            {
              viewBox: geometry.viewBox.join(' '),
              pathCount: geometry.paths.length,
              digest: geometryDigest(geometry.paths),
            },
          ];
        }),
      ),
    };
  }

  const barrel =
    HEADER +
    modules
      .map((m) => `export { ${m.component} } from './${m.stem}.js';\n`)
      .join('');

  return { modules, barrel, icons };
}

export function emitReactIcons(spec, fileVersion) {
  const { modules, barrel, icons } = renderReactIcons(spec);
  for (const m of modules) writeGenerated(join(OUT_DIR, m.file), m.tsx);
  writeGenerated(join(OUT_DIR, 'index.ts'), barrel);
  writeGenerated(
    join(OUT_DIR, 'icons.manifest.json'),
    JSON.stringify(
      {
        _note:
          'Written by the SOLAR codegen. One entry per icon; "digest" is a SHA-256 of the canonical JSON of that variant\'s paths, which is what the parity suite compares across targets. The path data itself is not repeated here: it is 358 KB and already lives in the generated modules.',
        target: 'react',
        fileVersion,
        icons,
      },
      null,
      2,
    ) + '\n',
  );
  return modules.length;
}
